// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.executorimport com.roshan.persona.brain.skill.SystemOperation/** * NOUS — Resource Category (Module 10 v2 — AtomicBatchCoordinator support). * * Classifies each [SystemOperation] by the Android hardware resource it * touches. Used by [AtomicBatchCoordinator] (Step 10.2) to decide whether * multiple operations can run in **parallel** (different categories — no * resource contention) or must run **sequentially** (same category — avoid * race conditions like two `AudioManager.adjustVolume` calls stomping * each other). * * ## Rules (per strategy v2 §"Compound Intent Dispatch" + audit defect H fix) * * | Operation | Category      | Reason | * |-----------|---------------|--------| * | SetTorch  | CAMERA        | CameraManager | * | AdjustVolume / SetVolume / SetRingerMode | AUDIO | AudioManager | * | SetDndMode | AUDIO       | NotificationManager (audio policy) | * | SetDisplayBrightness / LockScreen / SetKeepScreenOn | DISPLAY | WindowManager / Settings.System | * | SetWifi / SetBluetooth / SetAirplaneMode / SetLocationMode / SetTethering / SetNfc | CONNECTIVITY | System connectivity stack | * | OpenApp / OpenUrl | APP | PackageManager / Activity launches | * | SetAlarm / SetTimer | APP | AlarmClock intent launches clock app | * | CopyToClipboard | CLIPBOARD | ClipboardManager (no shared hardware) | * | PostNotification | NOTIFICATION | NotificationManager (no shared hardware) | * | SetBatterySaver | POWER | PowerManager (no audio/camera conflict) | * | SendSms / MakeCall | CONNECTIVITY | Telecom stack (Module 11 — but classified here for completeness) | * | Composite | SPECIAL | Handled by AtomicBatchCoordinator directly | * * ## Parallel vs Sequential Decision * * Given a batch of N operations: *  - Group by [resourceCategory]. *  - **Different categories** → run in parallel (coroutineScope + launch per group). *  - **Same category** → run sequentially within that group (avoid race). * * Example: "DND on, alarm 7 AM, lock screen" *  - DnD → AUDIO *  - Alarm → APP *  - Lock → DISPLAY *  → 3 different categories → 3 parallel coroutines → ~100 ms total (not 300 ms). * * Example: "Volume up × 3" *  - All AUDIO → 1 group → sequential execution → 3 × 30 ms = 90 ms. */enum class ResourceCategory {    /** Audio / ringer / DnD — AudioManager, NotificationManager. */    AUDIO,    /** Camera torch — CameraManager. */    CAMERA,    /** Display — Settings.System, WindowManager, AccessibilityService. */    DISPLAY,    /** Connectivity — WifiManager, BluetoothAdapter, ConnectivityManager, NfcAdapter. */    CONNECTIVITY,    /** App launches (OpenApp, OpenUrl, SetAlarm, SetTimer) — PackageManager / intents. */    APP,    /** Clipboard operations — ClipboardManager. */    CLIPBOARD,    /** Notification posting — NotificationManager. */    NOTIFICATION,    /** Power / battery — PowerManager. */    POWER,    /** Settings (legacy catch-all) — kept for backward compat with ops not yet reclassified. */    SETTINGS,    /** Special — Composite operations handled directly by AtomicBatchCoordinator. */    SPECIAL,}/** * Classify a [SystemOperation] into its [ResourceCategory]. * * Pure function — used by [SystemOperationExecutorImpl] and * [AtomicBatchCoordinator] for dispatch decisions. */object SystemOperationClassifier {    /**     * Map an operation to its resource category.     *     * Composite operations return [ResourceCategory.SPECIAL] — the     * coordinator unwraps them and classifies each child individually.     */    fun classify(operation: SystemOperation): ResourceCategory = when (operation) {        // Camera        is SystemOperation.SetTorch -> ResourceCategory.CAMERA        // Audio        is SystemOperation.AdjustVolume,        is SystemOperation.SetVolume,        is SystemOperation.SetRingerMode,        is SystemOperation.SetDndMode -> ResourceCategory.AUDIO        // Display        is SystemOperation.SetDisplayBrightness,        is SystemOperation.AdjustDisplayBrightness,        is SystemOperation.ScreenOn,        is SystemOperation.ScreenOff,        is SystemOperation.LockScreen,        is SystemOperation.SetKeepScreenOn -> ResourceCategory.DISPLAY        // Connectivity        is SystemOperation.SetWifi,        is SystemOperation.SetBluetooth,        is SystemOperation.SetAirplaneMode,        is SystemOperation.SetLocationMode,        is SystemOperation.SetTethering,        is SystemOperation.SetNfc,        is SystemOperation.SendSms,        is SystemOperation.MakeCall -> ResourceCategory.CONNECTIVITY        // App launches (intent-based — opens an Activity)        is SystemOperation.OpenApp,        is SystemOperation.OpenUrl,        is SystemOperation.SetAlarm,        is SystemOperation.SetTimer -> ResourceCategory.APP        // Clipboard        is SystemOperation.CopyToClipboard -> ResourceCategory.CLIPBOARD        // Notifications        is SystemOperation.PostNotification -> ResourceCategory.NOTIFICATION        // Power        is SystemOperation.SetBatterySaver -> ResourceCategory.POWER        // Composite — special handling        is SystemOperation.Composite -> ResourceCategory.SPECIAL    }    /**     * Group operations by resource category.     *     * Used by [AtomicBatchCoordinator] to decide parallel vs sequential dispatch.     */    fun groupByCategory(operations: List<SystemOperation>): Map<ResourceCategory, List<SystemOperation>> {        return operations.groupBy { classify(it) }    }    /**     * True if all operations are in the same category — they must run sequentially.     */    fun allSameCategory(operations: List<SystemOperation>): Boolean {        if (operations.isEmpty()) return true        val first = classify(operations.first())        return operations.all { classify(it) == first }    }    /**     * True if all operations are in different categories — they can run fully in parallel.     */    fun allDifferentCategories(operations: List<SystemOperation>): Boolean {        val categories = operations.map { classify(it) }        return categories.size == categories.toSet().size    }}